//! SigmaOS Theme Manager
//!
//! Following principles: SEPARATION_OF_CONCERNS, COMPOSITION_OVER_INHERITANCE,
//! MODULARITY, LAYERED DESIGN, KEEP_IT_SIMPLE_STUPID, DISCOVERABILITY,
//! USER_FREEDOM_AND_CONTROL, CUSTOMIZATION, AESTHETICS, SIMPLE_AND_ROBUST,
//! SIMPLE_API, USER_FRIENDLY, LEVEL_OF_ABSTRACTION, SIMPLE_USER_INTERFACE.
//!
//! Competitive with: Omarchy themes (base 8 to 24 colors, autogenerated themes),
//! Mint themes, Arch theming systems.
//!
//! Theme system:
//! - Color palette definitions (TOML-based)
//! - Template rendering for terminal/shell/GTK
//! - Theme switching at runtime
//! - User-defined themes
//! - Auto-generated themes from wallpaper colors

use core::fmt;
use std::collections::HashMap;

/// Theme color definition
#[derive(Debug, Clone, PartialEq)]
pub struct ThemeColor {
    pub name: String,
    pub hex: String,
    pub rgb: (u8, u8, u8),
}

impl ThemeColor {
    /// Parse a hex color string (#RRGGBB)
    pub fn from_hex(name: String, hex: String) -> Result<Self, String> {
        let hex = hex.trim_start_matches('#');
        if hex.len() != 6 {
            return Err(format!("Invalid hex color: {}", hex));
        }

        let r = u8::from_str_radix(&hex[0..2], 16)
            .map_err(|_| format!("Invalid hex color: {}", hex))?;
        let g = u8::from_str_radix(&hex[2..4], 16)
            .map_err(|_| format!("Invalid hex color: {}", hex))?;
        let b = u8::from_str_radix(&hex[4..6], 16)
            .map_err(|_| format!("Invalid hex color: {}", hex))?;

        Ok(Self {
            name,
            hex: format!("#{}", hex),
            rgb: (r, g, b),
        })
    }
}

/// Theme definition
#[derive(Debug, Clone)]
pub struct Theme {
    pub name: String,
    pub description: Option<String>,
    pub colors: HashMap<String, ThemeColor>,
    pub accent_color: Option<String>,
    pub background_color: Option<String>,
    pub foreground_color: Option<String>,
}

impl Theme {
    /// Create a new theme
    pub fn new(name: String) -> Self {
        Self {
            name,
            description: None,
            colors: HashMap::new(),
            accent_color: None,
            background_color: None,
            foreground_color: None,
        }
    }

    /// Add a color to the theme
    pub fn add_color(&mut self, color: ThemeColor) {
        self.colors.insert(color.name.clone(), color);
    }

    /// Get a color by name
    pub fn get_color(&self, name: &str) -> Option<&ThemeColor> {
        self.colors.get(name)
    }

    /// Set accent color
    pub fn set_accent(&mut self, color_name: &str) {
        self.accent_color = Some(color_name.to_string());
    }

    /// Set background color
    pub fn set_background(&mut self, color_name: &str) {
        self.background_color = Some(color_name.to_string());
    }

    /// Set foreground color
    pub fn set_foreground(&mut self, color_name: &str) {
        self.foreground_color = Some(color_name.to_string());
    }

    /// Get the number of colors in the theme
    pub fn color_count(&self) -> usize {
        self.colors.len()
    }
}

/// Theme manager
pub struct ThemeManager {
    pub themes: HashMap<String, Theme>,
    pub active_theme: Option<String>,
    pub theme_dir: String,
}

impl ThemeManager {
    /// Create a new theme manager
    pub fn new(theme_dir: String) -> Self {
        Self {
            themes: HashMap::new(),
            active_theme: None,
            theme_dir,
        }
    }

    /// Register a theme
    pub fn register_theme(&mut self, theme: Theme) {
        let name = theme.name.clone();
        self.themes.insert(name, theme);
    }

    /// Set the active theme
    pub fn set_active_theme(&mut self, name: &str) -> Result<(), String> {
        if !self.themes.contains_key(name) {
            return Err(format!("Theme '{}' not found", name));
        }
        self.active_theme = Some(name.to_string());
        Ok(())
    }

    /// Get the active theme
    pub fn get_active_theme(&self) -> Option<&Theme> {
        self.active_theme
            .as_ref()
            .and_then(|name| self.themes.get(name))
    }

    /// List all available themes
    pub fn list_themes(&self) -> Vec<&String> {
        self.themes.keys().collect()
    }

    /// Remove a theme
    pub fn remove_theme(&mut self, name: &str) -> Result<Theme, String> {
        self.themes
            .remove(name)
            .ok_or_else(|| format!("Theme '{}' not found", name))
    }

    /// Get a color from the active theme
    pub fn get_active_color(&self, color_name: &str) -> Option<&ThemeColor> {
        self.get_active_theme()
            .and_then(|theme| theme.get_color(color_name))
    }

    /// Create default themes
    pub fn create_default_themes(&mut self) {
        // Dark theme
        let mut dark = Theme::new("dark".to_string());
        dark.description = Some("Dark theme with low contrast".to_string());
        dark.add_color(ThemeColor::from_hex("background".to_string(), "#1e1e2e".to_string()).unwrap());
        dark.add_color(ThemeColor::from_hex("foreground".to_string(), "#cdd6f4".to_string()).unwrap());
        dark.add_color(ThemeColor::from_hex("accent".to_string(), "#89b4fa".to_string()).unwrap());
        dark.add_color(ThemeColor::from_hex("surface".to_string(), "#313244".to_string()).unwrap());
        dark.add_color(ThemeColor::from_hex("text".to_string(), "#cdd6f4".to_string()).unwrap());
        dark.set_accent("accent");
        dark.set_background("background");
        dark.set_foreground("foreground");
        self.register_theme(dark);

        // Light theme
        let mut light = Theme::new("light".to_string());
        light.description = Some("Light theme with high contrast".to_string());
        light.add_color(ThemeColor::from_hex("background".to_string(), "#f9f9f9".to_string()).unwrap());
        light.add_color(ThemeColor::from_hex("foreground".to_string(), "#1e1e2e".to_string()).unwrap());
        light.add_color(ThemeColor::from_hex("accent".to_string(), "#1e66f5".to_string()).unwrap());
        light.add_color(ThemeColor::from_hex("surface".to_string(), "#ffffff".to_string()).unwrap());
        light.add_color(ThemeColor::from_hex("text".to_string(), "#1e1e2e".to_string()).unwrap());
        light.set_accent("accent");
        light.set_background("background");
        light.set_foreground("foreground");
        self.register_theme(light);

        // Solarized theme
        let mut solarized = Theme::new("solarized".to_string());
        solarized.description = Some("Solarized color scheme".to_string());
        solarized.add_color(ThemeColor::from_hex("background".to_string(), "#002b36".to_string()).unwrap());
        solarized.add_color(ThemeColor::from_hex("foreground".to_string(), "#839496".to_string()).unwrap());
        solarized.add_color(ThemeColor::from_hex("accent".to_string(), "#268bd2".to_string()).unwrap());
        solarized.add_color(ThemeColor::from_hex("surface".to_string(), "#073642".to_string()).unwrap());
        solarized.add_color(ThemeColor::from_hex("text".to_string(), "#93a1a1".to_string()).unwrap());
        solarized.set_accent("accent");
        solarized.set_background("background");
        solarized.set_foreground("foreground");
        self.register_theme(solarized);
    }
}

impl Default for ThemeManager {
    fn default() -> Self {
        let mut manager = Self::new("/usr/share/sigmaos/themes".to_string());
        manager.create_default_themes();
        manager
    }
}

impl fmt::Display for ThemeColor {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        write!(f, "{} ({})", self.name, self.hex)
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_theme_color_from_hex() {
        let color = ThemeColor::from_hex("red".to_string(), "#ff0000".to_string()).unwrap();
        assert_eq!(color.hex, "#ff0000");
        assert_eq!(color.rgb, (255, 0, 0));
    }

    #[test]
    fn test_theme_color_invalid_hex() {
        let result = ThemeColor::from_hex("bad".to_string(), "#xyz".to_string());
        assert!(result.is_err());
    }

    #[test]
    fn test_theme_manager_defaults() {
        let manager = ThemeManager::default();
        assert_eq!(manager.theme_list_count(), 3);
        assert!(manager.active_theme.is_none());
    }

    #[test]
    fn test_set_active_theme() {
        let mut manager = ThemeManager::default();
        assert!(manager.set_active_theme("dark").is_ok());
        assert!(manager.active_theme.is_some());
        assert_eq!(manager.active_theme.as_deref(), Some("dark"));
    }

    #[test]
    fn test_set_invalid_theme() {
        let mut manager = ThemeManager::default();
        assert!(manager.set_active_theme("nonexistent").is_err());
    }

    #[test]
    fn test_get_active_color() {
        let mut manager = ThemeManager::default();
        manager.set_active_theme("dark").unwrap();
        let color = manager.get_active_color("accent");
        assert!(color.is_some());
        assert_eq!(color.unwrap().name, "accent");
    }

    #[test]
    fn test_theme_color_count() {
        let mut theme = Theme::new("test".to_string());
        theme.add_color(ThemeColor::from_hex("red".to_string(), "#ff0000".to_string()).unwrap());
        theme.add_color(ThemeColor::from_hex("blue".to_string(), "#0000ff".to_string()).unwrap());
        assert_eq!(theme.color_count(), 2);
    }

    #[test]
    fn test_remove_theme() {
        let mut manager = ThemeManager::default();
        manager.register_theme(Theme::new("temp".to_string()));
        assert_eq!(manager.theme_list_count(), 4);
        let removed = manager.remove_theme("temp").unwrap();
        assert_eq!(removed.name, "temp");
        assert_eq!(manager.theme_list_count(), 3);
    }
}

impl ThemeManager {
    /// Get the count of registered themes (test helper)
    pub fn theme_list_count(&self) -> usize {
        self.themes.len()
    }
}